package dev.pedro.learning.ecommerce.notification.api;import dev.pedro.learning.ecommerce.notification.domain.NotificationEntity;import java.time.Instant;import java.util.UUID;public record NotificationResponse(UUID id,UUID orderId,String email,int attempts,Instant sentAt){public static NotificationResponse from(NotificationEntity n){return new NotificationResponse(n.id,n.orderId,n.email,n.attempts,n.sentAt);}}